// Benny r23: copy of tools/lead21/audit_screen.mjs that also records Benny's projected screen box per shot (bbox.json)
// for Benny-centred crops (tools/benny23/crop_c.py). Round 21 lead audit (read-only): one playable screen of the REAL game at start / early / middle / late / end and hard
// left / right, deterministic (fixed sim steps, frozen shader clock, one frame rendered per shot, no real-time steps).
// Run from the worktree whose build you want to see (vite serves the current directory):
//   cd <worktree> && node /home/user/rainbow-/tools/lead21/audit_screen.mjs <outDir> <stage 04..08> "<query>"
// Shots are fractions of the stage from its checkpoint to its end; env AUDIT_SHOTS='[["name",frac,steer],...]' overrides.
import { mkdirSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
const [OUT, STAGE, Q] = process.argv.slice(2);
const SHOTS = process.env.AUDIT_SHOTS ? JSON.parse(process.env.AUDIT_SHOTS)
  : [['a_start', 0, null], ['b_early', 0.12, null], ['c_middle', 0.35, null], ['d_late', 0.6, null], ['e_end', 0.85, null],
     ['f_hard_left', 0.35, -1], ['g_hard_right', 0.35, 1]];
mkdirSync(OUT, { recursive: true });
const { chromium } = loadPlaywright();
const vite = await startVite(Number(process.env.AUDIT_PORT ?? 5290));
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
const log = [];
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  page.on('pageerror', (e) => console.error('pageerror', e.message));
  page.on('console', (m) => { if (m.type() === 'error' && /Shader|WebGL|rror/.test(m.text())) console.error('console', m.text().slice(0, 160)); });
  await page.goto(`${vite.url}/?qa=1&dpr=1&${Q}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 600000 });
  for (const [name, frac, steer] of SHOTS) {
    const st = await page.evaluate(async ([stage, frac, steer]) => {
      const r = window.__rainbow;
      r.goto(stage);
      const s0 = r.state().s, s1 = r.course.stage(stage).s1;
      const tS = s0 + frac * (s1 - s0);
      r.setSteer(steer);
      let k = 0; while (r.state().s < tS && k < 6000) { r.step(1); k++; }
      r.setSteer(null);
      r.freezeAt(10);
      r.drawList();
      await new Promise((res) => requestAnimationFrame(() => res()));
      // Benny's screen box: project the 8 corners of his world bounding box (fur shells included) with the live camera
      let box = null;
      try { box = window.__b20?.screenBox?.(r.camera()) ?? null; } catch (e) { box = String(e); }
      return { ...r.state(), s0, s1, box, bs: r.bennyScreen?.() };
    }, [STAGE, frac, steer]);
    await page.screenshot({ path: `${OUT}/${name}.png`, timeout: 600000 });
    log.push({ name, frac, steer, box: st.box, bs: st.bs, s: st.s, lat: st.lat, stage: st.stage, coins: st.coins, s0: st.s0, s1: st.s1 });
    console.log(STAGE, name, 's', st.s, 'lat', st.lat, 'stage', st.stage, 'coins', st.coins);
  }
} finally { writeFileSync(`${OUT}/shots.json`, JSON.stringify(log, null, 1)); await browser.close(); await vite.close?.(); }
----
"""Benny-centred close-up: crop a square-ish box around Benny's projected screen box (bbox from shots.json, the bounding box is loose (fur shells, hat), so 0.92 of it),
same 450x540 aspect as tools/benny20/crop.py, resized to 675x810 so it sits next to qa/benny/r22/approved/0N_benny.png.
usage: python3 -I tools/benny23/crop_c.py <shotDir>   (writes <name>_crop.png for every shot in shots.json)"""
import sys, json
from PIL import Image
d = sys.argv[1]
for s in json.load(open(f'{d}/shots.json')):
    im = Image.open(f"{d}/{s['name']}.png").convert('RGB')
    b = s.get('box')
    if not isinstance(b, list):
        b = [170, 900, 620, 1440]
    cx, cy = (b[0] + b[2]) / 2, (b[1] + b[3]) / 2
    h = max((b[3] - b[1]) * 0.92, (b[2] - b[0]) * 0.92 * 540 / 450, 200)
    w = h * 450 / 540
    x0, y0 = max(0, cx - w / 2), max(0, cy - h / 2)
    x0, y0 = min(x0, im.width - w), min(y0, im.height - h)
    im.crop((round(x0), round(y0), round(x0 + w), round(y0 + h))).resize((675, 810), Image.LANCZOS).save(f"{d}/{s['name']}_crop.png")

