/** per-screen fur exposure (LINEAR multipliers on the fur albedo above, which is solved for Screen 04). The approved
 *  pictures paint Benny lighter / pinker on 05–07 (fur mean ≈ (234, 82, 178), brightness median .95–.98) than on 04
 *  ((207, 74, 151), .84), while the game lights him less there. The game records its screen on
 *  benny.root.userData.stage (Game.ts setStage); runtime.ts eases the factor over ≈ 1 s. Unlisted screens: 04's look. */
export const EXPO20: Record<string, [number, number, number]> = {
  '05': lin('x05', [2.08, 1.54, 1.68]),
  '06': lin('x06', [1.73, 1.62, 1.5]),
  '07': lin('x07', [2.33, 1.59, 1.75]),
  '08': lin('x08', [2.0, 1.21, 1.7]),
};

const EXPO_ON = n('expo', 0) > 0;

/** beanie geometry on top of benny05's HAT05 (hat-local). Measured at the 04 start view against the approved silhouette
 *  (tools/benny20/score.py): cuff bottom on the centre column 1276 → 1271 px target, pompom 168 px wide like the approved */
export const HAT20 = {
  /** uniform scale of the whole beanie (cuff, crown, star, pompom) about the head centre */
  scale: n('hs', 1.1),
  /** extra drop along the body's up axis (units) */
  drop: n('hd', 0.02),
  /** backward tilt about the hat's X axis (rad, − = top toward his back): the BACK of the cuff (what the rear chase
   *  cameras see) comes down to the approved seat while the FRONT stays above his eyes (eye tops ≈ +0.18) */
  tilt: n('ht', -0.23),
  /** body-fur bald zone under the cuff: cos of the cone angle around the (tilted) hat up axis (GLB 0.414) */
  baldW: n('bw', 0.38),
  /** pompom: extra scale and lift (hat-local, after the beanie scale) */
  pomScale: n('ps', 1.03),
  pomDY: n('pdy', 0.0),
  /** star felt patch: thickness factor (GLB bevelled star ≈ 0.11 thick) */
  starFlat: n('sf', 0.3),
};

/** colour factors (LINEAR multipliers on the knit / felt maps, solved like the fur) + knit normal strength.
 *  r23 step 1: the `knit_mode: chain` maps (tools/benny20/knit.py, vertical rib cords, cream light stripes) carry their
 *  colour solved through the 04 light + post chain, so the knit factors are neutral. */
const MAT20 = {
  crown: lin('ccol', [1, 1, 1]),
  brim: lin('rcol', [1, 1, 1]),
  star: lin('scol', [0.34, 0.75, 1.0]),
  crownN: n('kcn', 2.0),
  brimN: n('kbn', 2.0),
};

/** r23 step 1: per-screen knit exposure, like EXPO20 for the fur. The approved 05–08 paint the beanie ≈ 1.5× brighter
 *  than the game lights it there (white stripes, bright violet), and each screen's light tints it differently, so the
 *  violet yarn (`v`) and the light CREAM yarn (`w`) get their own LINEAR multipliers (knit shader: the map texel's g / b
 *  ratio tells the two yarns apart). Solved per screen against the approved hat (violet median) and a cream target for
 *  the light stripes (not lavender). Applied only with `b20knit=1&b20expo=1`; overridable `&b20kv0N=r,g,b` /
 *  `&b20kw0N=r,g,b`. Unlisted screens (04): 1. */
export const KNITX20: Record<string, { v: [number, number, number]; w: [number, number, number] }> = {
  '05': { v: lin('kv05', [1.3, 1.3, 1.85]), w: lin('kw05', [1.5, 1.6, 1.5]) },
  '06': { v: lin('kv06', [1.65, 1.8, 1.42]), w: lin('kw06', [1.6, 1.9, 1.58]) },
  '07': { v: lin('kv07', [1.6, 0.9, 1.86]), w: lin('kw07', [1.6, 1.7, 1.6]) },
  '08': { v: lin('kv08', [1.75, 1.6, 2.1]), w: lin('kw08', [1.3, 1.45, 1.3]) },
};

/** r23 step 3: per-screen felt-star exposure (LINEAR multipliers on the felt star colour; with `b20star=1&b20expo=1`).
 *  The approved 05–08 paint the star a brighter YELLOW gold (≈ (251, 215, 30), hue ≈ 51°) than the 04 amber (hue 42°);
 *  each screen's light pushes the felt toward orange there. Overridable `&b20sx0N=r,g,b`. Unlisted (04): 1. */
export const STARX20: Record<string, [number, number, number]> = {
  '05': lin('sx05', [0.9, 1.3, 0.7]),
  '06': lin('sx06', [0.95, 2.1, 0.8]),
  '07': lin('sx07', [0.9, 1.3, 0.6]),
  '08': lin('sx08', [0.9, 1.3, 0.75]),
};

const T = (f: string) => new URL(`../../../assets/textures/benny20/${f}`, import.meta.url).href;
const FILES = ['crown.png', 'crown_n.png', 'brim.png', 'brim_n.png', 'star.png', 'star_n.png', 'star_felt.png', 'star_felt_n.png'];
let loaded: Promise<Record<string, THREE.Texture | null>> | null = null;
/** load the knit / felt maps once (missing file → null: that part keeps its benny05 look) */
export function loadBenny20Maps(): Promise<Record<string, THREE.Texture | null>> {
  if (loaded) return loaded;
  const tl = new THREE.TextureLoader();

}
const knitMats = KNIT_ON && EXPO_ON
  ? ['hat_crown', 'hat_brim']
      .map((nm) => (get(nm) as THREE.Mesh | undefined)?.material as THREE.MeshStandardMaterial | undefined)
      .filter((m): m is THREE.MeshStandardMaterial => !!m?.map)
      .map((m) => m.userData.knitU as { uKnitV: { value: THREE.Vector3 }; uKnitW: { value: THREE.Vector3 } })
  : [];

// ---- star: flat stitched felt patch ----
// r23 step 3, opt-in `&b20star=1`: puffy stitched FELT star (tools/benny20/knit.py `star_mode: felt`, params
// tools/benny23/star_r23.json): golden felt pillow, lighter orange sewn rim (inner band + the mesh bevel as one band),
// running stitch of light dashes / dark needle holes; colour solved through the live 04 light + post chain.
const star = get('hat_star') as THREE.Mesh | undefined;
const FELT = n('star', 0) > 0 && !!maps['star_felt.png'];
if (star && maps['star.png']) {
  star.scale.z *= HAT20.starFlat;
  const mat = (star.material as THREE.MeshStandardMaterial).clone();
  mat.map = FELT ? maps['star_felt.png'] : maps['star.png'];
  mat.normalMap = FELT ? maps['star_felt_n.png'] : maps['star_n.png'];
  mat.normalScale.setScalar(FELT ? n('sfn', 1.5) : 1);
  mat.color.setRGB(...(FELT ? lin('sfcol', [0.55, 0.85, 1.0]) : MAT20.star));
  mat.roughness = 0.97;
  mat.metalness = 0;
  mat.emissive.setRGB(1, 0.72, 0.2);
  mat.emissiveIntensity = FELT ? n('sfe', 0) : n('se', 0.08);
  mat.needsUpdate = true;
  star.material = mat;
}
const starX = FELT && EXPO_ON && star ? { m: star.material as THREE.MeshStandardMaterial, base: (star.material as THREE.MeshStandardMaterial).color.clone() } : null;

// ---- per-screen fur exposure (body + arms) ----
const expo = furs.filter((f) => /^fur_(body|arm)/.test(f.mesh.name)).map((f) => ({ f, base: f.material.color.clone() }));
const cur = new THREE.Vector3(1, 1, 1);
const tgt = new THREE.Vector3();
const kvCur = new THREE.Vector3(1, 1, 1);
const kwCur = new THREE.Vector3(1, 1, 1);
const kvTgt = new THREE.Vector3();
const sxCur = new THREE.Vector3(1, 1, 1);
const sxTgt = new THREE.Vector3();
const kwTgt = new THREE.Vector3();
let first = true;
const lastPos = new THREE.Vector3();
const pos = new THREE.Vector3();
const tick: Benny20Tick = (dt, stage) => {
  // opt-in `&b20expo=1` until proven in motion on 05–07 (step-1 pictures were made without it)
  const e = (EXPO_ON && stage && EXPO20[stage]) || [1, 1, 1];
  tgt.set(e[0], e[1], e[2]);
  // ease while riding from one screen into the next; snap on the first frame and after a jump (checkpoint / QA goto)
  scene.getWorldPosition(pos);
  const jumped = pos.distanceTo(lastPos) > 5;
  lastPos.copy(pos);
  const ke = (stage && KNITX20[stage]) || { v: [1, 1, 1], w: [1, 1, 1] };
  kvTgt.set(...ke.v);
  kwTgt.set(...ke.w);
  sxTgt.set(...((stage && STARX20[stage]) || [1, 1, 1]));
  if (first || jumped) { cur.copy(tgt); kvCur.copy(kvTgt); kwCur.copy(kwTgt); sxCur.copy(sxTgt); first = false; } else {
    const a = 1 - Math.exp(-dt * 3);
    cur.lerp(tgt, a);
    kvCur.lerp(kvTgt, a);
    kwCur.lerp(kwTgt, a);
    sxCur.lerp(sxTgt, a);
  }
  if (starX) starX.m.color.setRGB(starX.base.r * sxCur.x, starX.base.g * sxCur.y, starX.base.b * sxCur.z);
  for (const { f, base } of expo) f.material.color.setRGB(base.r * cur.x, base.g * cur.y, base.b * cur.z);
  for (const k of knitMats) { k.uKnitV.value.copy(kvCur); k.uKnitW.value.copy(kwCur); }
};

// QA only (`?qa` pages, read by tools/benny20/probe.mjs): live handles for tuning without a reload
if (QS?.has('qa') && typeof window !== 'undefined') {
  /** QA (tools/benny23/shots_c.mjs): Benny's screen box in pixels for the live camera returned by __rainbow.camera() */
  const screenBox = (c: { matrixWorld: number[]; fov: number; aspect: number; near: number; far: number; width: number; height: number }) => {
    const cam = new THREE.PerspectiveCamera(c.fov, c.aspect, c.near, c.far);
    cam.matrixWorld.fromArray(c.matrixWorld);
    cam.matrixWorldInverse.copy(cam.matrixWorld).invert();
    const bb = new THREE.Box3().setFromObject(scene);
    let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
    for (let i = 0; i < 8; i++) {
      const v = new THREE.Vector3(i & 1 ? bb.max.x : bb.min.x, i & 2 ? bb.max.y : bb.min.y, i & 4 ? bb.max.z : bb.min.z).project(cam);
      const px = (v.x * 0.5 + 0.5) * c.width, py = (0.5 - v.y * 0.5) * c.height;
      x0 = Math.min(x0, px); y0 = Math.min(y0, py); x1 = Math.max(x1, px); y1 = Math.max(y1, py);
    }
    return [Math.round(x0), Math.round(y0), Math.round(x1), Math.round(y1)];
  };
  (window as unknown as { __b20?: unknown }).__b20 = { scene, furs, hat, pom, star, HAT20, LOCK20, EXPO20, expo, KNITX20, knitMats, STARX20, starX, screenBox };
}
return tick;

